CREATE OR REPLACE FUNCTION calculate_disf(
    p_airtempc numeric,
    p_atmostransparency numeric,
    p_humidityrate numeric,
    p_lunardistdeg numeric
)
RETURNS numeric AS $$
DECLARE
    v_disf numeric;
BEGIN
    v_disf := (10 - ABS(p_airtempc - 15) / 10.0) 
              * p_atmostransparency 
              * (1 - p_humidityrate / 200.0) 
              * ((100 - p_lunardistdeg) / 100.0);

    RETURN v_disf;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION calculate_disf(
    p_airtempc numeric,
    p_atmostransparency numeric,
    p_humidityrate numeric,
    p_lunardistdeg numeric,
    p_min_threshold numeric DEFAULT 0
)
RETURNS numeric AS $$
DECLARE
    v_disf numeric;
BEGIN
    v_disf := (10 - ABS(p_airtempc - 15) / 10.0) 
              * p_atmostransparency 
              * (1 - p_humidityrate / 200.0) 
              * ((100 - p_lunardistdeg) / 100.0);

    IF v_disf < p_min_threshold THEN
        v_disf := p_min_threshold;
    END IF;

    RETURN v_disf;
END;
$$ LANGUAGE plpgsql;
